from threading import Thread
from taf.sbts.oam.coam.admin.exceptions import TimeoutReached


class AsyncTask(object):
    """Class useful for running keywords in a separate thread"""

    def __init__(self, instance, keyword_name, *args, **kwargs):
        name = kwargs.get("alias", "default")
        if "connection" in kwargs:
            name = kwargs.get("connection")
        self._task_name = "AsyncTask: {} args={} kwargs={}".format(keyword_name, args, kwargs)
        self._instance = instance
        self._keyword_name = keyword_name
        self._worker = Thread(target=self._execute_in_thread, args=(self._get_target_keyword(), args, kwargs))
        self._is_finished = False
        self._logger = instance.store.get(name).get_logger()

    def __str__(self):
        return self._task_name

    def start(self):
        """Start worker thread."""
        self._logger.enable_buffering()
        self._is_finished = False
        self._worker.start()

    def collect_result(self, timeout):
        """Collect result from a given function that was run in thread."""
        self._worker.join(timeout)
        self._logger.flush()
        self._logger.disable_buffering()
        if not self._is_finished:
            raise TimeoutReached("{} not finished within timeout: {}".format(self._task_name, timeout))
        if isinstance(self._result, Exception):
            raise self._result  # pylint: disable-msg=E0702
        return self._result

    def _execute_in_thread(self, keyword, args, kwargs):
        try:
            self._result = keyword(*args, **kwargs)
        except Exception as e:
            self._result = e
        finally:
            self._is_finished = True
            self._logger.disable_buffering()

    def _get_target_keyword(self):
        return getattr(self._instance, self._keyword_name.strip().lower().replace(" ", "_"))
